272	import com.pousadamarealta.domain.enums.RatePlan;
273	import com.pousadamarealta.domain.model.Document;
274	import com.pousadamarealta.domain.model.Reservation;
275	import com.pousadamarealta.dto.CreateReservationRequest;
276	import com.pousadamarealta.dto.DocumentResponse;
277	import com.pousadamarealta.dto.ErrorResponse;
278	import com.pousadamarealta.dto.ReservationResponse;
279	import com.pousadamarealta.service.DocumentService;
280	import com.pousadamarealta.service.ReservationService;
281	import io.javalin.http.Context;
282	
283	import java.time.LocalDate;
284	import java.time.format.DateTimeParseException;
285	
286	public class ReservationController {
287	    private final ReservationService reservationService;
288	    private final DocumentService documentService;
289	
290	    public ReservationController(ReservationService reservationService, DocumentService documentService) {
291	        this.reservationService = reservationService;
292	        this.documentService = documentService;
293	    }
294	
295	    public void createReservation(Context ctx) {
296	        try {
297	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
298	
299	            validateRequest(request);
300	
301	            LocalDate checkIn = LocalDate.parse(request.checkIn());
302	            LocalDate checkOut = LocalDate.parse(request.checkOut());
303	            RatePlan ratePlan = RatePlan.valueOf(request.ratePlan());
304	
305	            Reservation reservation = reservationService.createReservation(
306	                request.roomNumber(),
307	                request.guestName(),
308	                request.guestEmail(),
309	                request.guestCpf(),
310	                checkIn,
311	                checkOut,
312	                request.guests(),
313	                ratePlan
314	            );
315	
316	            ctx.status(201).json(ReservationResponse.from(reservation));
317	        } catch (DateTimeParseException | IllegalArgumentException e) {
318	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
319	        } catch (ReservationService.RoomNotFoundException e) {
320	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
321	        } catch (ReservationService.RoomUnavailableException e) {
322	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
323	        } catch (ReservationService.CapacityExceededException e) {
324	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
325	        } catch (ReservationService.InvalidRequestException e) {
326	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
327	        }
328	    }
329	
330	    public void getReservation(Context ctx) {
331	        try {
332	            Long id = Long.parseLong(ctx.pathParam("id"));
333	            Reservation reservation = reservationService.getReservation(id)
334	                    .orElseThrow(() -> new ReservationService.ReservationNotFoundException(id));
335	            ctx.json(ReservationResponse.from(reservation));
336	        } catch (NumberFormatException e) {
337	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
338	        } catch (ReservationService.ReservationNotFoundException e) {
339	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
340	        }
341	    }
342	
343	    public void confirmReservation(Context ctx) {
344	        try {
345	            Long id = Long.parseLong(ctx.pathParam("id"));
346	            Reservation reservation = reservationService.confirmReservation(id);
347	            ctx.json(ReservationResponse.from(reservation));
348	        } catch (NumberFormatException e) {
349	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
350	        } catch (ReservationService.ReservationNotFoundException e) {
351	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
352	        } catch (ReservationService.OperationNotAllowedException | IllegalStateException e) {
353	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
354	        }
355	    }
356	
357	    public void cancelReservation(Context ctx) {
358	        try {
359	            Long id = Long.parseLong(ctx.pathParam("id"));
360	            Reservation reservation = reservationService.cancelReservation(id);
361	            ctx.json(ReservationResponse.from(reservation));
362	        } catch (NumberFormatException e) {
363	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
364	        } catch (ReservationService.ReservationNotFoundException e) {
365	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
366	        } catch (ReservationService.OperationNotAllowedException | IllegalStateException e) {
367	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
368	        }
369	    }
370	
371	    public void checkIn(Context ctx) {
372	        try {
373	            Long id = Long.parseLong(ctx.pathParam("id"));
374	            Reservation reservation = reservationService.checkIn(id);
375	            ctx.json(ReservationResponse.from(reservation));
376	        } catch (NumberFormatException e) {
377	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
378	        } catch (ReservationService.ReservationNotFoundException e) {
379	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
380	        } catch (ReservationService.OperationNotAllowedException | IllegalStateException e) {
381	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
382	        }
383	    }
384	
385	    public void checkOut(Context ctx) {
386	        try {
387	            Long id = Long.parseLong(ctx.pathParam("id"));
388	            Reservation reservation = reservationService.checkOut(id);
389	            Document document = documentService.generateDocument(reservation);
390	            ctx.json(DocumentResponse.from(document));
391	        } catch (NumberFormatException e) {
392	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
393	        } catch (ReservationService.ReservationNotFoundException e) {
394	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
395	        } catch (ReservationService.OperationNotAllowedException | IllegalStateException e) {
396	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
397	        }
398	    }
399	
400	    public void getDocument(Context ctx) {
401	        try {
402	            Long id = Long.parseLong(ctx.pathParam("id"));
403	            Reservation reservation = reservationService.getReservation(id)
404	                    .orElseThrow(() -> new ReservationService.ReservationNotFoundException(id));
405	
406	            if (!reservation.isPaid()) {
407	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED",
408	                    "Document only available for paid reservations"));
409	                return;
410	            }
411	
412	            Document document = documentService.generateDocument(reservation);
413	            ctx.json(DocumentResponse.from(document));
414	        } catch (NumberFormatException e) {
415	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
416	        } catch (ReservationService.ReservationNotFoundException e) {
417	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
418	        }
419	    }
420	
421	    private void validateRequest(CreateReservationRequest request) {
422	        if (request.roomNumber() == null || request.roomNumber().isBlank()) {
423	            throw new ReservationService.InvalidRequestException("Room number is required");
424	        }
425	        if (request.guestName() == null || request.guestName().isBlank()) {
426	            throw new ReservationService.InvalidRequestException("Guest name is required");
427	        }
428	        if (request.guestEmail() == null || request.guestEmail().isBlank()) {
429	            throw new ReservationService.InvalidRequestException("Guest email is required");
430	        }
431	        if (request.guestCpf() == null || request.guestCpf().isBlank()) {
432	            throw new ReservationService.InvalidRequestException("Guest CPF is required");
433	        }
434	        if (request.checkIn() == null || request.checkIn().isBlank()) {
435	            throw new ReservationService.InvalidRequestException("Check-in date is required");
436	        }
437	        if (request.checkOut() == null || request.checkOut().isBlank()) {
438	            throw new ReservationService.InvalidRequestException("Check-out date is required");
439	        }
440	        if (request.ratePlan() == null || request.ratePlan().isBlank()) {
441	            throw new ReservationService.InvalidRequestException("Rate plan is required");
442	        }
443	    }
444	}
