295	    public void createReservation(Context ctx) {
296	        try {
297	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
298	
299	            validateRequest(request);
300	
301	            LocalDate checkIn = LocalDate.parse(request.checkIn());
302	            LocalDate checkOut = LocalDate.parse(request.checkOut());
303	            RatePlan ratePlan = RatePlan.valueOf(request.ratePlan());
304	
305	            Reservation reservation = reservationService.createReservation(
306	                request.roomNumber(),
307	                request.guestName(),
308	                request.guestEmail(),
309	                request.guestCpf(),
310	                checkIn,
311	                checkOut,
312	                request.guests(),
313	                ratePlan
314	            );
315	
316	            ctx.status(201).json(ReservationResponse.from(reservation));
317	        } catch (DateTimeParseException | IllegalArgumentException e) {
318	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
319	        } catch (ReservationService.RoomNotFoundException e) {
320	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
