134	import java.math.BigDecimal;
135	import java.math.RoundingMode;
136	import java.time.LocalDate;
137	import java.time.Month;
138	import java.util.Optional;
139	
140	public class ReservationService {
141	    private final ReservationRepository reservationRepository;
142	    private final RoomRepository roomRepository;
143	    private final EventPublisher eventPublisher;
144	
145	    public ReservationService(ReservationRepository reservationRepository,
146	                            RoomRepository roomRepository,
147	                            EventPublisher eventPublisher) {
148	        this.reservationRepository = reservationRepository;
149	        this.roomRepository = roomRepository;
150	        this.eventPublisher = eventPublisher;
151	    }
152	
153	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
154	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
155	        Room room = roomRepository.findByNumber(roomNumber)
156	                .orElseThrow(() -> new RoomNotFoundException(roomNumber));
157	
158	        if (guests < 1) {
159	            throw new InvalidRequestException("Guests must be at least 1");
160	        }
161	
162	        if (guests > room.getCapacity()) {
163	            throw new CapacityExceededException(room.getCapacity(), guests);
164	        }
165	
166	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
167	            throw new InvalidRequestException("Check-out must be after check-in");
168	        }
169	
170	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
171	            throw new RoomUnavailableException(roomNumber);
172	        }
173	
174	        BigDecimal nightlyRate = calculateNightlyRate(room.getNightlyRate(), checkIn, checkOut);
175	
176	        Reservation reservation = Reservation.create(
177	            roomNumber, guestName, guestEmail, guestCpf,
178	            checkIn, checkOut, guests, ratePlan, nightlyRate
179	        );
180	
181	        return reservationRepository.save(reservation);
182	    }
183	
184	    public Optional<Reservation> getReservation(Long id) {
185	        return reservationRepository.findById(id);
186	    }
187	
188	    public Reservation confirmReservation(Long id) {
189	        Reservation reservation = reservationRepository.findById(id)
190	                .orElseThrow(() -> new ReservationNotFoundException(id));
191	
192	        if (reservation.getStatus() != ReservationStatus.PENDING) {
193	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
194	        }
195	
196	        reservation.confirm();
197	        reservationRepository.save(reservation);
198	
199	        eventPublisher.publish(new ReservationConfirmedEvent(reservation));
200	
201	        return reservation;
202	    }
203	
204	    public Reservation cancelReservation(Long id) {
205	        Reservation reservation = reservationRepository.findById(id)
206	                .orElseThrow(() -> new ReservationNotFoundException(id));
207	
208	        if (reservation.getStatus() != ReservationStatus.PENDING &&
209	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
210	            throw new OperationNotAllowedException("Only pending or confirmed reservations can be cancelled");
211	        }
212	
213	        boolean wasConfirmed = reservation.getStatus() == ReservationStatus.CONFIRMED;
214	        reservation.cancel();
215	        reservationRepository.save(reservation);
216	
217	        eventPublisher.publish(new ReservationCancelledEvent(reservation, wasConfirmed));
218	
219	        return reservation;
220	    }
221	
222	    public Reservation checkIn(Long id) {
223	        Reservation reservation = reservationRepository.findById(id)
224	                .orElseThrow(() -> new ReservationNotFoundException(id));
225	
226	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
227	            throw new OperationNotAllowedException("Only confirmed reservations can be checked in");
228	        }
229	
230	        reservation.checkIn();
231	        return reservationRepository.save(reservation);
232	    }
233	
234	    public Reservation checkOut(Long id) {
235	        Reservation reservation = reservationRepository.findById(id)
236	                .orElseThrow(() -> new ReservationNotFoundException(id));
237	
238	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
239	            throw new OperationNotAllowedException("Only checked-in reservations can be checked out");
240	        }
241	
242	        reservation.checkOut();
243	        return reservationRepository.save(reservation);
244	    }
245	
246	    private BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
247	        BigDecimal totalRate = BigDecimal.ZERO;
248	        int nights = 0;
249	
250	        LocalDate current = checkIn;
251	        while (current.isBefore(checkOut)) {
252	            BigDecimal rate = baseRate;
253	            if (isHighSeason(current)) {
254	                rate = rate.multiply(new BigDecimal("1.20"))
255	                          .setScale(2, RoundingMode.HALF_EVEN);
256	            }
257	            totalRate = totalRate.add(rate);
258	            nights++;
259	            current = current.plusDays(1);
260	        }
261	
262	        return totalRate.divide(new BigDecimal(nights), 2, RoundingMode.HALF_EVEN);
263	    }
264	
265	    private boolean isHighSeason(LocalDate date) {
266	        Month month = date.getMonth();
267	        int day = date.getDayOfMonth();
268	
269	        if (month == Month.JULY) {
270	            return true;
271	        }
272	
273	        if (month == Month.DECEMBER && day >= 15) {
274	            return true;
275	        }
276	
277	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
278	            return true;
279	        }
280	
281	        return false;
282	    }
