385	public class FinanceNotificationListener implements EventListener {
386	    private static final String FINANCE_EMAIL = "financeiro@pousadamarealta.com.br";
387	    private static final DecimalFormat MONEY_FORMATTER;
388	
389	    static {
390	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
391	        symbols.setGroupingSeparator('.');
392	        symbols.setDecimalSeparator(',');
393	        MONEY_FORMATTER = new DecimalFormat("#,##0.00", symbols);
394	    }
395	
396	    private final MessageRepository messageRepository;
397	
398	    public FinanceNotificationListener(MessageRepository messageRepository) {
399	        this.messageRepository = messageRepository;
400	    }
401	
402	    @Override
403	    public void handle(ReservationEvent event) {
404	        if (event instanceof ReservationConfirmedEvent) {
405	            notifyPayment((ReservationConfirmedEvent) event);
406	        } else if (event instanceof ReservationCancelledEvent cancelledEvent) {
407	            if (cancelledEvent.wasConfirmed() && hasRefund(cancelledEvent.getReservation())) {
408	                notifyRefund(cancelledEvent);
409	            }
410	        }
411	    }
412	
413	    private void notifyPayment(ReservationConfirmedEvent event) {
414	        Reservation reservation = event.getReservation();
415	
416	        String subject = String.format("Pagamento recebido - reserva %d", reservation.getId());
417	        String body = formatMoney(reservation.getAmountPaid());
418	
419	        Message message = Message.email(FINANCE_EMAIL, subject, body);
420	        messageRepository.save(message);
421	    }
422	
423	    private void notifyRefund(ReservationCancelledEvent event) {
424	        Reservation reservation = event.getReservation();
425	
426	        String subject = String.format("Reembolso - reserva %d", reservation.getId());
427	        String body = formatMoney(reservation.getRefund());
428	
429	        Message message = Message.email(FINANCE_EMAIL, subject, body);
430	        messageRepository.save(message);
431	    }
432	
433	    private boolean hasRefund(Reservation reservation) {
434	        return reservation.getRefund() != null &&
435	               reservation.getRefund().compareTo(BigDecimal.ZERO) > 0;
436	    }
437	
438	    private String formatMoney(BigDecimal amount) {
439	        return "R$ " + MONEY_FORMATTER.format(amount);
440	    }
441	}
