460	public class GuestNotificationListener implements EventListener {
461	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
462	    private static final DecimalFormat MONEY_FORMATTER;
463	
464	    static {
465	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
466	        symbols.setGroupingSeparator('.');
467	        symbols.setDecimalSeparator(',');
468	        MONEY_FORMATTER = new DecimalFormat("#,##0.00", symbols);
469	    }
470	
471	    private final MessageRepository messageRepository;
472	    private final RoomRepository roomRepository;
473	
474	    public GuestNotificationListener(MessageRepository messageRepository, RoomRepository roomRepository) {
475	        this.messageRepository = messageRepository;
476	        this.roomRepository = roomRepository;
477	    }
478	
479	    @Override
480	    public void handle(ReservationEvent event) {
481	        if (event instanceof ReservationConfirmedEvent) {
482	            sendConfirmationEmail((ReservationConfirmedEvent) event);
483	        }
484	    }
485	
486	    private void sendConfirmationEmail(ReservationConfirmedEvent event) {
487	        Reservation reservation = event.getReservation();
488	        RoomType roomType = roomRepository.findByNumber(reservation.getRoomNumber())
489	                .orElseThrow()
490	                .getType();
491	
492	        String receipt = buildReceipt(reservation, roomType);
493	        String body = buildConfirmationBody(reservation.getGuestName(), receipt);
494	
495	        Message message = Message.email(
496	            reservation.getGuestEmail(),
497	            "Reserva confirmada - Pousada Maré Alta",
498	            body
499	        );
500	
501	        messageRepository.save(message);
502	    }
503	
504	    private String buildReceipt(Reservation reservation, RoomType roomType) {
505	        StringBuilder sb = new StringBuilder();
506	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
507	        sb.append("Hóspede: ").append(reservation.getGuestName())
508	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
509	        sb.append("Quarto: ").append(reservation.getRoomNumber())
510	          .append(" (").append(roomType).append(")\n");
511	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
512	          .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
513	          .append(" | ").append(reservation.getNights())
514	          .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
515	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
516	
517	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
518	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
519	        }
520	
521	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
522	
523	        return sb.toString();
524	    }
525	
526	    private String buildConfirmationBody(String guestName, String receipt) {
527	        return String.format(
528	            "Olá, %s!\n\n" +
529	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
530	            "%s\n\n" +
531	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
532	            "Até breve!",
533	            guestName, receipt
534	        );
535	    }
536	
537	    private String formatDate(LocalDate date) {
538	        return date.format(DATE_FORMATTER);
539	    }
540	
541	    private String formatMoney(BigDecimal amount) {
542	        return "R$ " + MONEY_FORMATTER.format(amount);
543	    }
544	
545	    private String formatCpf(String cpf) {
546	        if (cpf.length() == 11) {
547	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
548	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
549	        }
550	        return cpf;
551	    }
552	}
