 80	public class Reservation {
 81	    private Long id;
 82	    private final String roomNumber;
 83	    private final String guestName;
 84	    private final String guestEmail;
 85	    private final String guestCpf;
 86	    private final LocalDate checkIn;
 87	    private final LocalDate checkOut;
 88	    private final int guests;
 89	    private final RatePlan ratePlan;
 90	    private final BigDecimal nightlyRate;
 91	    private ReservationStatus status;
 92	    private BigDecimal amountPaid;
 93	    private BigDecimal refund;
 94	
 95	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
 96	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
 97	                      BigDecimal nightlyRate, ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
 98	        this.id = id;
 99	        this.roomNumber = roomNumber;
100	        this.guestName = guestName;
101	        this.guestEmail = guestEmail;
102	        this.guestCpf = guestCpf;
103	        this.checkIn = checkIn;
104	        this.checkOut = checkOut;
105	        this.guests = guests;
106	        this.ratePlan = ratePlan;
107	        this.nightlyRate = nightlyRate;
108	        this.status = status;
109	        this.amountPaid = amountPaid;
110	        this.refund = refund;
111	    }
112	
113	    public static Reservation create(String roomNumber, String guestName, String guestEmail, String guestCpf,
114	                                    LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
115	                                    BigDecimal nightlyRate) {
116	        return new Reservation(null, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
117	                guests, ratePlan, nightlyRate, ReservationStatus.PENDING, BigDecimal.ZERO, null);
118	    }
119	
120	    public void setId(Long id) {
121	        this.id = id;
122	    }
123	
124	    public Long getId() {
125	        return id;
126	    }
127	
128	    public String getRoomNumber() {
129	        return roomNumber;
130	    }
131	
132	    public String getGuestName() {
133	        return guestName;
134	    }
135	
136	    public String getGuestEmail() {
137	        return guestEmail;
138	    }
139	
140	    public String getGuestCpf() {
141	        return guestCpf;
142	    }
143	
144	    public LocalDate getCheckIn() {
145	        return checkIn;
146	    }
147	
148	    public LocalDate getCheckOut() {
149	        return checkOut;
150	    }
151	
152	    public int getGuests() {
153	        return guests;
154	    }
155	
156	    public RatePlan getRatePlan() {
157	        return ratePlan;
158	    }
159	
160	    public BigDecimal getNightlyRate() {
161	        return nightlyRate;
162	    }
163	
164	    public ReservationStatus getStatus() {
165	        return status;
166	    }
167	
168	    public BigDecimal getAmountPaid() {
169	        return amountPaid;
170	    }
171	
172	    public BigDecimal getRefund() {
173	        return refund;
174	    }
175	
176	    public int getNights() {
177	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
178	    }
179	
180	    public BigDecimal getSubtotal() {
181	        return nightlyRate.multiply(new BigDecimal(getNights()))
182	                .setScale(2, RoundingMode.HALF_EVEN);
183	    }
184	
185	    public BigDecimal getDiscount() {
186	        BigDecimal subtotal = getSubtotal();
187	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate())
188	                .setScale(2, RoundingMode.HALF_EVEN);
189	        return discount;
190	    }
191	
192	    public BigDecimal getTotal() {
193	        return getSubtotal().subtract(getDiscount())
194	                .setScale(2, RoundingMode.HALF_EVEN);
195	    }
196	
197	    public void confirm() {
198	        if (status != ReservationStatus.PENDING) {
199	            throw new IllegalStateException("Only pending reservations can be confirmed");
200	        }
201	        this.status = ReservationStatus.CONFIRMED;
202	        this.amountPaid = getTotal();
203	    }
204	
205	    public void cancel() {
206	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
207	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
208	        }
209	
210	        boolean wasConfirmed = status == ReservationStatus.CONFIRMED;
211	        this.status = ReservationStatus.CANCELLED;
212	
213	        if (wasConfirmed && ratePlan == RatePlan.STANDARD) {
214	            this.refund = amountPaid;
215	        } else {
216	            this.refund = BigDecimal.ZERO;
217	        }
218	    }
219	
220	    public void checkIn() {
221	        if (status != ReservationStatus.CONFIRMED) {
222	            throw new IllegalStateException("Only confirmed reservations can be checked in");
223	        }
224	        this.status = ReservationStatus.CHECKED_IN;
225	    }
226	
227	    public void checkOut() {
228	        if (status != ReservationStatus.CHECKED_IN) {
229	            throw new IllegalStateException("Only checked-in reservations can be checked out");
230	        }
231	        this.status = ReservationStatus.CHECKED_OUT;
232	    }
233	
234	    public boolean isActive() {
235	        return status != ReservationStatus.CANCELLED;
236	    }
237	
238	    public boolean isPaid() {
239	        return status == ReservationStatus.CONFIRMED ||
240	               status == ReservationStatus.CHECKED_IN ||
241	               status == ReservationStatus.CHECKED_OUT;
242	    }
243	}
