  1	package com.pousadamarealta.domain.model;
  2	
  3	import com.pousadamarealta.domain.enums.RatePlan;
  4	import com.pousadamarealta.domain.enums.ReservationStatus;
  5	
  6	import java.math.BigDecimal;
  7	import java.math.RoundingMode;
  8	import java.time.LocalDate;
  9	import java.time.temporal.ChronoUnit;
 10	
 11	public class Reservation {
 12	    private Long id;
 13	    private final String roomNumber;
 14	    private final String guestName;
 15	    private final String guestEmail;
 16	    private final String guestCpf;
 17	    private final LocalDate checkIn;
 18	    private final LocalDate checkOut;
 19	    private final int guests;
 20	    private final RatePlan ratePlan;
 21	    private final BigDecimal nightlyRate;
 22	    private ReservationStatus status;
 23	    private BigDecimal amountPaid;
 24	    private BigDecimal refund;
 25	
 26	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
 27	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
 28	                      BigDecimal nightlyRate, ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
 29	        this.id = id;
 30	        this.roomNumber = roomNumber;
 31	        this.guestName = guestName;
 32	        this.guestEmail = guestEmail;
 33	        this.guestCpf = guestCpf;
 34	        this.checkIn = checkIn;
 35	        this.checkOut = checkOut;
 36	        this.guests = guests;
 37	        this.ratePlan = ratePlan;
 38	        this.nightlyRate = nightlyRate;
 39	        this.status = status;
 40	        this.amountPaid = amountPaid;
 41	        this.refund = refund;
 42	    }
 43	
 44	    public static Reservation create(String roomNumber, String guestName, String guestEmail, String guestCpf,
 45	                                    LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
 46	                                    BigDecimal nightlyRate) {
 47	        return new Reservation(null, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
 48	                guests, ratePlan, nightlyRate, ReservationStatus.PENDING, BigDecimal.ZERO, null);
 49	    }
 50	
 51	    public void setId(Long id) {
 52	        this.id = id;
 53	    }
 54	
 55	    public Long getId() {
 56	        return id;
 57	    }
 58	
 59	    public String getRoomNumber() {
 60	        return roomNumber;
 61	    }
 62	
 63	    public String getGuestName() {
 64	        return guestName;
 65	    }
 66	
 67	    public String getGuestEmail() {
 68	        return guestEmail;
 69	    }
 70	
 71	    public String getGuestCpf() {
 72	        return guestCpf;
 73	    }
 74	
 75	    public LocalDate getCheckIn() {
 76	        return checkIn;
 77	    }
 78	
 79	    public LocalDate getCheckOut() {
 80	        return checkOut;
 81	    }
 82	
 83	    public int getGuests() {
 84	        return guests;
 85	    }
 86	
 87	    public RatePlan getRatePlan() {
 88	        return ratePlan;
 89	    }
 90	
 91	    public BigDecimal getNightlyRate() {
 92	        return nightlyRate;
 93	    }
 94	
 95	    public ReservationStatus getStatus() {
 96	        return status;
 97	    }
 98	
 99	    public BigDecimal getAmountPaid() {
100	        return amountPaid;
101	    }
102	
103	    public BigDecimal getRefund() {
104	        return refund;
105	    }
106	
107	    public int getNights() {
108	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
109	    }
110	
111	    public BigDecimal getSubtotal() {
112	        return nightlyRate.multiply(new BigDecimal(getNights()))
113	                .setScale(2, RoundingMode.HALF_EVEN);
114	    }
115	
116	    public BigDecimal getDiscount() {
117	        BigDecimal subtotal = getSubtotal();
118	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate())
119	                .setScale(2, RoundingMode.HALF_EVEN);
120	        return discount;
121	    }
122	
123	    public BigDecimal getTotal() {
124	        return getSubtotal().subtract(getDiscount())
125	                .setScale(2, RoundingMode.HALF_EVEN);
126	    }
127	
128	    public void confirm() {
129	        if (status != ReservationStatus.PENDING) {
130	            throw new IllegalStateException("Only pending reservations can be confirmed");
131	        }
132	        this.status = ReservationStatus.CONFIRMED;
133	        this.amountPaid = getTotal();
134	    }
135	
136	    public void cancel() {
137	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
138	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
139	        }
140	
141	        boolean wasConfirmed = status == ReservationStatus.CONFIRMED;
142	        this.status = ReservationStatus.CANCELLED;
143	
144	        if (wasConfirmed && ratePlan == RatePlan.STANDARD) {
145	            this.refund = amountPaid;
146	        } else {
147	            this.refund = BigDecimal.ZERO;
148	        }
149	    }
150	
151	    public void checkIn() {
152	        if (status != ReservationStatus.CONFIRMED) {
153	            throw new IllegalStateException("Only confirmed reservations can be checked in");
154	        }
155	        this.status = ReservationStatus.CHECKED_IN;
156	    }
157	
158	    public void checkOut() {
159	        if (status != ReservationStatus.CHECKED_IN) {
160	            throw new IllegalStateException("Only checked-in reservations can be checked out");
161	        }
162	        this.status = ReservationStatus.CHECKED_OUT;
163	    }
164	
165	    public boolean isActive() {
166	        return status != ReservationStatus.CANCELLED;
167	    }
168	
169	    public boolean isPaid() {
170	        return status == ReservationStatus.CONFIRMED ||
171	               status == ReservationStatus.CHECKED_IN ||
172	               status == ReservationStatus.CHECKED_OUT;
173	    }
174	}
