 84	
 85	public class ReservationRepository {
 86	
 87	    public Reservation save(Reservation reservation) {
 88	        if (reservation.getId() == null) {
 89	            return insert(reservation);
 90	        } else {
 91	            return update(reservation);
 92	        }
 93	    }
 94	
 95	    private Reservation insert(Reservation reservation) {
 96	        String sql = """
 97	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
 98	                                     check_in, check_out, guests, rate_plan, nightly_rate,
 99	                                     status, amount_paid, refund)
100	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
101	            RETURNING id
102	            """;
103	
104	        try (Connection conn = Database.getConnection();
105	             PreparedStatement stmt = conn.prepareStatement(sql)) {
106	
107	            setStatementParameters(stmt, reservation);
108	
109	            try (ResultSet rs = stmt.executeQuery()) {
110	                if (rs.next()) {
111	                    reservation.setId(rs.getLong("id"));
112	                }
113	            }
114	
115	            return reservation;
116	        } catch (SQLException e) {
117	            throw new RuntimeException("Failed to insert reservation", e);
118	        }
119	    }
120	
121	    private Reservation update(Reservation reservation) {
122	        String sql = """
123	            UPDATE reservations
124	            SET room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?,
125	                check_in = ?, check_out = ?, guests = ?, rate_plan = ?, nightly_rate = ?,
126	                status = ?, amount_paid = ?, refund = ?
127	            WHERE id = ?
128	            """;
129	
130	        try (Connection conn = Database.getConnection();
131	             PreparedStatement stmt = conn.prepareStatement(sql)) {
132	
133	            setStatementParameters(stmt, reservation);
134	            stmt.setLong(13, reservation.getId());
135	            stmt.executeUpdate();
136	
137	            return reservation;
138	        } catch (SQLException e) {
139	            throw new RuntimeException("Failed to update reservation", e);
140	        }
141	    }
142	
143	    private void setStatementParameters(PreparedStatement stmt, Reservation reservation) throws SQLException {
144	        stmt.setString(1, reservation.getRoomNumber());
145	        stmt.setString(2, reservation.getGuestName());
146	        stmt.setString(3, reservation.getGuestEmail());
147	        stmt.setString(4, reservation.getGuestCpf());
148	        stmt.setDate(5, Date.valueOf(reservation.getCheckIn()));
149	        stmt.setDate(6, Date.valueOf(reservation.getCheckOut()));
150	        stmt.setInt(7, reservation.getGuests());
151	        stmt.setString(8, reservation.getRatePlan().name());
152	        stmt.setBigDecimal(9, reservation.getNightlyRate());
153	        stmt.setString(10, reservation.getStatus().name());
154	        stmt.setBigDecimal(11, reservation.getAmountPaid());
155	
156	        if (reservation.getRefund() != null) {
157	            stmt.setBigDecimal(12, reservation.getRefund());
158	        } else {
159	            stmt.setNull(12, Types.DECIMAL);
160	        }
161	    }
162	
163	    public Optional<Reservation> findById(Long id) {
164	        String sql = """
165	            SELECT id, room_number, guest_name, guest_email, guest_cpf,
166	                   check_in, check_out, guests, rate_plan, nightly_rate,
167	                   status, amount_paid, refund
168	            FROM reservations
169	            WHERE id = ?
170	            """;
171	
172	        try (Connection conn = Database.getConnection();
173	             PreparedStatement stmt = conn.prepareStatement(sql)) {
174	            stmt.setLong(1, id);
175	
176	            try (ResultSet rs = stmt.executeQuery()) {
177	                if (rs.next()) {
178	                    return Optional.of(mapRow(rs));
179	                }
180	            }
181	        } catch (SQLException e) {
182	            throw new RuntimeException("Failed to find reservation", e);
183	        }
184	
185	        return Optional.empty();
186	    }
187	
188	    public boolean hasConflict(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
189	        String sql = """
190	            SELECT COUNT(*) as count
191	            FROM reservations
192	            WHERE room_number = ?
193	              AND status != 'CANCELLED'
194	              AND check_in < ?
195	              AND check_out > ?
196	              AND (? IS NULL OR id != ?)
197	            """;
198	
199	        try (Connection conn = Database.getConnection();
200	             PreparedStatement stmt = conn.prepareStatement(sql)) {
201	            stmt.setString(1, roomNumber);
202	            stmt.setDate(2, Date.valueOf(checkOut));
203	            stmt.setDate(3, Date.valueOf(checkIn));
204	
205	            if (excludeReservationId != null) {
206	                stmt.setLong(4, excludeReservationId);
207	                stmt.setLong(5, excludeReservationId);
208	            } else {
209	                stmt.setNull(4, Types.BIGINT);
210	                stmt.setNull(5, Types.BIGINT);
211	            }
212	
213	            try (ResultSet rs = stmt.executeQuery()) {
214	                if (rs.next()) {
215	                    return rs.getInt("count") > 0;
216	                }
217	            }
218	        } catch (SQLException e) {
219	            throw new RuntimeException("Failed to check conflicts", e);
220	        }
221	
222	        return false;
223	    }
224	
225	    public List<Reservation> findByCheckInMonth(int year, int month) {
226	        String sql = """
227	            SELECT id, room_number, guest_name, guest_email, guest_cpf,
228	                   check_in, check_out, guests, rate_plan, nightly_rate,
229	                   status, amount_paid, refund
230	            FROM reservations
231	            WHERE EXTRACT(YEAR FROM check_in) = ?
232	              AND EXTRACT(MONTH FROM check_in) = ?
233	            ORDER BY check_in, id
234	            """;
235	
236	        List<Reservation> reservations = new ArrayList<>();
237	
238	        try (Connection conn = Database.getConnection();
239	             PreparedStatement stmt = conn.prepareStatement(sql)) {
240	            stmt.setInt(1, year);
241	            stmt.setInt(2, month);
242	
243	            try (ResultSet rs = stmt.executeQuery()) {
244	                while (rs.next()) {
245	                    reservations.add(mapRow(rs));
246	                }
247	            }
248	        } catch (SQLException e) {
249	            throw new RuntimeException("Failed to find reservations by month", e);
250	        }
251	
252	        return reservations;
253	    }
254	
255	    public List<Reservation> findByDate(LocalDate date) {
256	        String sql = """
257	            SELECT id, room_number, guest_name, guest_email, guest_cpf,
258	                   check_in, check_out, guests, rate_plan, nightly_rate,
259	                   status, amount_paid, refund
260	            FROM reservations
261	            WHERE check_in <= ?
262	              AND check_out > ?
263	              AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
264	            ORDER BY room_number
265	            """;
266	
267	        List<Reservation> reservations = new ArrayList<>();
268	
269	        try (Connection conn = Database.getConnection();
270	             PreparedStatement stmt = conn.prepareStatement(sql)) {
271	            stmt.setDate(1, Date.valueOf(date));
272	            stmt.setDate(2, Date.valueOf(date));
273	
274	            try (ResultSet rs = stmt.executeQuery()) {
275	                while (rs.next()) {
276	                    reservations.add(mapRow(rs));
277	                }
278	            }
279	        } catch (SQLException e) {
280	            throw new RuntimeException("Failed to find reservations by date", e);
281	        }
282	
283	        return reservations;
284	    }
285	
286	    private Reservation mapRow(ResultSet rs) throws SQLException {
287	        BigDecimal refund = rs.getBigDecimal("refund");
288	
289	        return new Reservation(
290	            rs.getLong("id"),
291	            rs.getString("room_number"),
292	            rs.getString("guest_name"),
293	            rs.getString("guest_email"),
294	            rs.getString("guest_cpf"),
295	            rs.getDate("check_in").toLocalDate(),
296	            rs.getDate("check_out").toLocalDate(),
297	            rs.getInt("guests"),
298	            RatePlan.valueOf(rs.getString("rate_plan")),
299	            rs.getBigDecimal("nightly_rate"),
300	            ReservationStatus.valueOf(rs.getString("status")),
301	            rs.getBigDecimal("amount_paid"),
302	            rs.wasNull() ? null : refund
303	        );
304	    }
305	}
