   231	    static class InMemoryReservationRepository extends ReservationRepository {
   232	        private final List<Reservation> reservations = new ArrayList<>();
   233	        private long nextId = 1;
   234	
   235	        @Override
   236	        public Reservation save(Reservation reservation) {
   237	            if (reservation.getId() == null) {
   238	                reservation.setId(nextId++);
   239	                reservations.add(reservation);
   240	            }
   241	            return reservation;
   242	        }
   243	
   244	        @Override
   245	        public Optional<Reservation> findById(Long id) {
   246	            return reservations.stream()
   247	                    .filter(r -> r.getId().equals(id))
   248	                    .findFirst();
   249	        }
   250	
   251	        @Override
   252	        public boolean hasConflict(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
   253	            return reservations.stream()
   254	                    .filter(r -> r.getRoomNumber().equals(roomNumber))
   255	                    .filter(r -> r.isActive())
   256	                    .filter(r -> excludeReservationId == null || !r.getId().equals(excludeReservationId))
   257	                    .anyMatch(r -> r.getCheckIn().isBefore(checkOut) && r.getCheckOut().isAfter(checkIn));
   258	        }
   259	    }
